mapper.select:
SELECT * FROM ( SELECT TO_CHAR(R.BASE_DT, 'YYYY-MM-DD') AS baseDt, R.STK_CD AS stkCd, R.STK_NM AS stkNm, R.MKT_CD AS mktCd, M.MKT_CD AS listingMarket, R.CUR_PRICE AS curPrice, R.MON_OPEN_PRICE AS monOpenPrice, R.MA5 AS ma5, R.MA20 AS ma20, R.MA60 AS ma60, R.MA120 AS ma120, R.MA240 AS ma240, R.GOLDEN_YN AS goldenYn, R.MON_UP_YN AS monUpYn, R.MON_CHG_RATE AS monChgRate, R.TREND_STRENGTH AS trendStrength, R.AVG_TRD_VAL_20 AS avgTrdVal20, R.REC_YN AS recYn, R.REC_GRADE AS recGrade, R.REC_REASON AS recReason FROM TB_REC_SIGNAL R JOIN TB_STK_MASTER M ON M.STK_CD = R.STK_CD JOIN (
SELECT STK_CD, MKT_CD, MAX(BASE_DT) AS LATEST_DT FROM TB_REC_SIGNAL
MKT_CD = #{mktGroup,jdbcType=VARCHAR}
AND BASE_DT <= TO_DATE(#{baseDt,jdbcType=VARCHAR}, 'YYYY-MM-DD')
GROUP BY STK_CD, MKT_CD ) L ON L.STK_CD = R.STK_CD AND L.MKT_CD = R.MKT_CD AND L.LATEST_DT = R.BASE_DT WHERE 1 = 1
AND R.MKT_CD = #{mktGroup,jdbcType=VARCHAR}
AND M.MKT_CD = 'KOSPI' AND M.MKT_CD = 'KOSDAQ' AND M.MKT_CD = 'NASDAQ' AND M.MKT_CD = 'NYSE' AND M.INDEX_CD = 'KOSPI200' AND M.INDEX_CD = 'KOSDAQ150' AND M.INDEX_CD = 'DOW' AND M.INDEX_CD = 'SNP500' AND M.INDEX_CD = 'NDX100'
AND M.STK_TYPE = #{stockType,jdbcType=VARCHAR}
AND M.USE_YN = #{useYn,jdbcType=VARCHAR}
AND ${dynamicWhere}
ORDER BY
R.MON_CHG_RATE R.TREND_STRENGTH R.AVG_TRD_VAL_20 R.CUR_PRICE R.STK_NM R.TREND_STRENGTH
ASC NULLS LAST DESC NULLS LAST
) WHERE ROWNUM <=
#{limit,jdbcType=NUMERIC} 500

SELECT STK_CD AS stkCd, TO_CHAR(TRADE_DT, 'YYYYMMDD') AS tradeDt, ADJ_OPEN_PRICE AS adjOpenPrice, ADJ_HIGH_PRICE AS adjHighPrice, ADJ_LOW_PRICE AS adjLowPrice, ADJ_CLOSE_PRICE AS adjClosePrice, VOLUME AS volume, TRADE_VALUE AS tradeValue FROM TB_STK_DLY_PRICE WHERE TRADE_DT >= TO_DATE(#{fromDt,jdbcType=VARCHAR}, 'YYYY-MM-DD') AND TRADE_DT <= TO_DATE(#{toDt,jdbcType=VARCHAR}, 'YYYY-MM-DD') AND STK_CD IN
#{stkCd,jdbcType=VARCHAR}
ORDER BY STK_CD, TRADE_DT ASC
